import{z as B,x as l,o as t,c as d,q as o,j as s,D as r,d as E,s as A,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"研究文档","description":"","frontmatter":{"title":"研究文档","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-research-docs.md","filePath":"quant/rc2-research-docs.md","lastUpdated":1791063341000}'),c={name:"quant/rc2-research-docs.md"};function p(D,a,h,u,C,f){const n=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="研究文档" tabindex="-1">研究文档 <a class="header-anchor" href="#研究文档" aria-label="Permalink to &quot;研究文档&quot;">​</a></h1><div class="epigraph"><p>研究文档里最贵的一段，是「我们为什么放弃」；没有它，组织会用同样的学费再交一次。</p><footer>—— 据 Arnott, Harvey and Markowitz, A Backtesting Protocol in the Era of Machine Learning, Journal of Financial Data Science, 2019 与站内研究复盘的归档口径整理</footer></div><p><a href="/quant/rc2-code-review">上一课</a>的清单守住了代码与配置，但研究最有价值的部分不在 diff 里：假设为什么立、判据定在哪、为什么半途放弃——这些只住在作者脑子里，脑子会离职、会失忆、会把运气记成判断。本课写研究文档：一页假设文档的最小结构，以及它从活文档到冻结案例的两段生命。它是<a href="/quant/research-postmortem">研究复盘</a>四件沉淀物在写作端的展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>研究论证有三个去处，全都不可靠：notebook 的叙述格（跟着输出漂移）、会议上的口头汇报（当天就失真）、作者的记性（把 \\(N\\) 次尝试压缩成一个「我们试过」）。缺口是一份<strong>独立于代码与人脑的论证载体</strong>，它要同时满足三个属性：可追溯（每句结论挂得上证据）、可冻结（定案时刻定版）、可检索（半年后能被搜到）。缺了它，评审、审计与接手全都退化成考古——<a href="/quant/rc2-repro-package-standard">复现包</a>让人能重跑你的计算，文档让人能重走你的推理；后者不比前者便宜。</p><p><span class="marginnote">直觉类比：复现包是料理包，加热就能得到同一道菜；研究文档是厨师的创作笔记——为什么选这个火候、试过哪种配料不行、放弃的那版差在哪。半年后想改进这道菜的人，加热料理包只能吃到原味，创作笔记才告诉他下一步往哪改。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="一页假设文档" tabindex="-1">一页假设文档 <a class="header-anchor" href="#一页假设文档" aria-label="Permalink to &quot;一页假设文档&quot;">​</a></h3><p>六栏，一页写完。<strong>问题</strong>：这项研究要回答什么，为什么值得回答（源头见<a href="/quant/research-question-origination">研究问题的来源</a>）。<strong>数据</strong>：快照 ID 与清洗规则引用，不写「数据库里的日频数据」。<strong>方法</strong>：计算核位置与配置指纹。<strong>判据</strong>：主指标与放弃线，提案时预注册，先于任何结果存在——这是<a href="/quant/research-log-discipline">研究日志纪律</a>主指标预锁的文档落点。<strong>结果</strong>：只写登记过的实验 ID，不手抄数字。<strong>死因或迁移条件</strong>：放弃要写死因，继续要写条件。</p>',9)),(t(),s(i,null,{default:r(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E6%8F%90%E6%A1%88%EF%BC%9A%E4%B8%80%E9%A1%B5%E6%96%87%E6%A1%A3%20%E5%88%A4%E6%8D%AE%E9%A2%84%E6%B3%A8%E5%86%8C%22%5D%20--%3E%20EXP%5B%22%E5%AE%9E%E9%AA%8C%EF%BC%9A%E7%99%BB%E8%AE%B0%20ID%20%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20EXP%20--%3E%20UPD%7B%22%E7%BB%93%E6%9E%9C%E5%AF%B9%E4%B8%8A%E5%88%A4%E6%8D%AE%EF%BC%9F%22%7D%0A%20%20UPD%20--%3E%7C%E7%BB%A7%E7%BB%AD%7C%20COND%5B%22%E6%9B%B4%E6%96%B0%E8%BF%81%E7%A7%BB%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20COND%20--%3E%20EXP%0A%20%20UPD%20--%3E%7C%E6%94%BE%E5%BC%83%7C%20DEAD%5B%22%E5%86%99%E6%AD%BB%E5%9B%A0%20%E5%BD%92%E6%A1%A3%E8%B4%9F%E7%BB%93%E6%9E%9C%22%5D%0A%20%20UPD%20--%3E%7C%E5%AE%9A%E6%A1%88%7C%20FRZ%5B%22%E5%86%BB%E7%BB%93%EF%BC%9A%E6%96%87%E6%A1%A3%20%2B%20%E5%A4%8D%E7%8E%B0%E5%8C%85%E4%BA%92%E9%93%BE%22%5D%0A%20%20FRZ%20--%3E%20CASE%5B%22%E8%BF%9B%E6%A1%88%E4%BE%8B%E5%BA%93%20%E5%8F%AF%E6%A3%80%E7%B4%A2%22%5D%0A%20%20DEAD%20--%3E%20CASE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("文档的两段生命对应两种不同的写作纪律。"),e("strong",null,"活文档期"),E("：提案与探索阶段随便改，版本由代码仓库管，与代码同一个 diff 流（上一课的评审顺带覆盖文档改动）；这一阶段的关键纪律只有一条——判据栏在见到结果之前就填好，之后不许回填。"),e("strong",null,"冻结期"),E("：定案或放弃时，文档与复现包互链、同刻冻结，成为案例：结果挂台账指纹，结论挂判据，审计从任何一句结论可以一键回溯到实验与快照。这正是回测协议要求的「决策按时间记录」在写作上的兑现：文档的时间戳与内容绑定，回填无处遁形。")],-1)),a[5]||(a[5]=e("p",null,[E("为什么「死因」一栏最值钱：研究的产出里，负结果占大多数，而组织天然只流传成功案例。死因写成「效果不好」等于没写——它不落在判据上，不告诉后来者"),e("strong",null,"哪条路在什么条件下不通"),E("。写成「在 2015 前样本内有效、样本外衰减到零，判据是样本外 IR 大于 0.5，未达」——同样一句放弃，变成了可检索、可引用、可推翻的证据。半年后有人想重试同一片沼泽，搜到的是一条带判据的死因，而不是一片空白。")],-1)),(t(),s(i,null,{default:r(()=>[A(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E6%A0%B7%E6%9C%AC%E5%A4%96%20IR%200.62%22%5D%20--%3E%20B%5B%22%E5%88%A4%E6%8D%AE%EF%BC%9AIR%20%5Cgt%200.5%20%E9%A2%84%E6%B3%A8%E5%86%8C%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%AE%9E%E9%AA%8C%20ID%EF%BC%9AEXP-0417%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%8F%B0%E8%B4%A6%E6%8C%87%E7%BA%B9%EF%BC%9A%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%20%2B%20commit%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%20ID%20%E4%B8%8D%E5%8F%AF%E5%8F%98%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%B8%85%E6%B4%97%E8%A7%84%E5%88%99%E7%89%88%E6%9C%AC%22%5D%0A%20%20F%20--%3E%20G%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">这张图回答的问题与上图不同：上图是文档的一生怎么走，这张是审计员怎么从一句话走回原始数据——「可追溯」不是形容词，是这样一条每环都落在不可变存储上的链。术语翻译：「冻结」不是从此不许改，是定版存档：此后修改的唯一合法方式是开新版本并注明理由，旧版仍在——像会计只做红字冲销，不改旧账。</span></p><p><span class="marginnote">统计各团队文档的空栏率，「死因或迁移条件」几乎总排第一。它空着的原因不是懒，是没有预注册的判据——没有判据，「放弃」就找不到落点，只能含糊其辞。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>文档不替代数据：它引用实验与快照，本身不承载结果表的全量——引用断了，文档退化为散文，所以引用靶标必须落在不可变存储。它也不写成论文：一页是硬约束，超过一页说明判据不清，而不是研究深刻。更不要求文采：六栏填实比写得漂亮有用得多。最后，活文档期不等于无纪律——探索期的改判可以，改判要留痕；冻结之后再改内容的唯一合法方式是开新版本并注明理由，直接改历史是<a href="/quant/de-data-versioning">数据版本化</a>禁的那条路在文档上的翻版。</p><p><span class="marginnote">常见误区：初学者容易把「一页」的硬约束当成不重视，越写越长以显得严谨。实际上超过一页几乎总说明判据没定清楚——论证发散是因为不知道什么算完成；六栏各一句话的文档，比三十页的综述更能通过评审，因为评审查的是证据链，不是字数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文档是独立于代码与人脑的论证载体：可追溯、可冻结、可检索，三者缺一即考古。</li><li>一页六栏：问题、数据引用、方法与指纹、预注册判据、结果挂实验 ID、死因或迁移条件。</li><li>两段生命：活文档期与代码同 diff，冻结期与复现包互链成案例。</li><li>死因必须落在判据上；负结果可检索，组织才不会用同样的学费再交一次。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；站内<a href="/quant/research-postmortem">研究复盘</a>、<a href="/quant/research-log-discipline">研究日志纪律</a>、<a href="/quant/research-question-origination">研究问题的来源</a>各课。</li></ul>',7))])}const F=B(c,[["render",p]]);export{g as __pageData,F as default};
